// Discord bot as a Cloudflare Pages advanced-mode worker (_worker.js).
//
// Discord sends every button press, dropdown, form and slash command here as an HTTPS
// request (an "interactions endpoint"), so no always-on connection or server is needed.
// Handles: verification with a code check, tickets with transcripts, staff commands.
//
// Environment: DISCORD_TOKEN (secret, required), KV (KV namespace binding, optional:
// ticket numbers, cooldowns, raid mode, lockdown memory).
// CONFIG below is generated by build_worker.py from layout.py + state.json.

const CONFIG = /*CONFIG*/ {};
const PAGES = /*PAGES*/ {};   // path -> HTML (Terms of Service, Privacy Policy), built from worker/legal/*.md

const API = "https://discord.com/api/v10";
const EPHEMERAL = 64;
const COLOR = CONFIG.color;
const RED = 0xe74c3c, ORANGE = 0xe67e22, GREEN = 0x2ecc71, GREY = 0x95a5a6;
const ADMINISTRATOR = 8n;
const LOCK_BITS = { send_messages: 1n << 11n, send_messages_in_threads: 1n << 38n, add_reactions: 1n << 6n, connect: 1n << 20n };
const TALK = (1n << 10n) | (1n << 11n) | (1n << 15n) | (1n << 14n) | (1n << 16n); // view, send, attach, embed, history

// ── Plumbing ──────────────────────────────────────────────────────────────────

const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json" } });
const reply = (content, extra = {}) => json({ type: 4, data: { content, flags: EPHEMERAL, allowed_mentions: { parse: [] }, ...extra } });
const update = (data) => json({ type: 7, data: { allowed_mentions: { parse: [] }, ...data } });
const deferred = () => json({ type: 5, data: { flags: EPHEMERAL } });

function hexToBytes(hex) {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.substr(i * 2, 2), 16);
  return out;
}

async function verifySignature(request, body) {
  const sig = request.headers.get("X-Signature-Ed25519");
  const ts = request.headers.get("X-Signature-Timestamp");
  if (!sig || !ts || !/^[0-9a-f]{128}$/i.test(sig)) return false;
  const data = new TextEncoder().encode(ts + body);
  for (const alg of [{ name: "Ed25519" }, { name: "NODE-ED25519", namedCurve: "NODE-ED25519" }]) {
    try {
      const key = await crypto.subtle.importKey("raw", hexToBytes(CONFIG.public_key), alg, false, ["verify"]);
      return await crypto.subtle.verify(alg, key, hexToBytes(sig), data);
    } catch (e) { /* try the next algorithm name */ }
  }
  return false;
}

async function discord(env, method, path, body, { reason, form } = {}) {
  const headers = { Authorization: `Bot ${env.DISCORD_TOKEN}`, "User-Agent": "DiscordBot (pages-bot, 1.0)" };
  if (reason) headers["X-Audit-Log-Reason"] = encodeURIComponent(reason).slice(0, 500);
  let payload;
  if (form) payload = form;
  else if (body !== undefined) { headers["Content-Type"] = "application/json"; payload = JSON.stringify(body); }
  for (let attempt = 0; attempt < 3; attempt++) {
    const res = await fetch(API + path, { method, headers, body: payload });
    if (res.status === 429) {
      const wait = (await res.json().catch(() => ({}))).retry_after ?? 1;
      await new Promise((r) => setTimeout(r, wait * 1000 + 100));
      continue;
    }
    const text = await res.text();
    if (!res.ok) throw new Error(`${method} ${path} -> ${res.status} ${text.slice(0, 300)}`);
    return text ? JSON.parse(text) : null;
  }
  throw new Error(`${method} ${path}: rate limited`);
}

const kvGet = (env, k) => (env.KV ? env.KV.get(k) : null);
const kvPut = (env, k, v, ttl) => (env.KV ? env.KV.put(k, String(v), ttl ? { expirationTtl: Math.max(60, ttl) } : undefined) : null);
const kvDel = (env, k) => (env.KV ? env.KV.delete(k) : null);

async function hmac(env, text) {
  const raw = await crypto.subtle.digest("SHA-256", new TextEncoder().encode("captcha:" + env.DISCORD_TOKEN));
  const key = await crypto.subtle.importKey("raw", raw, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(text)));
  return [...sig.slice(0, 8)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

const snowflakeTime = (id) => Number((BigInt(id) >> 22n) + 1420070400000n);
const relTime = (ms) => `<t:${Math.floor(ms / 1000)}:R>`;
const clip = (s, n = 1000) => (!s ? "*(empty)*" : s.length <= n ? s : s.slice(0, n - 1) + "…");

function hasRole(member, keys) {
  if ((BigInt(member.permissions || "0") & ADMINISTRATOR) === ADMINISTRATOR) return true;
  const ids = keys.map((k) => CONFIG.roles[k]).filter(Boolean);
  return member.roles.some((r) => ids.includes(r));
}

async function log(env, channelKey, embed, extra = {}) {
  const ch = CONFIG.channels[channelKey];
  if (!ch) return;
  try {
    await discord(env, "POST", `/channels/${ch}/messages`, { embeds: [{ timestamp: new Date().toISOString(), ...embed }], allowed_mentions: { parse: [] }, ...extra });
  } catch (e) { console.log("log failed", e.message); }
}

async function followup(env, interaction, data) {
  return discord(env, "PATCH", `/webhooks/${CONFIG.app_id}/${interaction.token}/messages/@original`, { allowed_mentions: { parse: [] }, ...data });
}

// ── Verification ──────────────────────────────────────────────────────────────

async function startVerify(env, it) {
  const m = it.member, uid = m.user.id;
  if (m.roles.includes(CONFIG.roles.member)) return reply("You're already verified.");
  if ((await kvGet(env, "raid")) === "on")
    return reply("Verification is paused for a moment while staff deal with a raid. Please try again later.");
  const ageDays = (Date.now() - snowflakeTime(uid)) / 86400000;
  if (ageDays < CONFIG.security.min_account_age_days) {
    await log(env, "member-log", { title: "Verification blocked: new account", color: ORANGE,
      description: `<@${uid}> (created ${relTime(snowflakeTime(uid))}). Staff can \`/verify\` them.` });
    return reply(`Your Discord account is newer than ${CONFIG.security.min_account_age_days} days, so you can't verify automatically. Staff have been notified and can verify you manually.`);
  }
  const until = Number(await kvGet(env, `vfail:${uid}`)) || 0;
  if (until > Date.now()) return reply(`Try again ${relTime(until)}.`);

  const code = String(Math.floor(Math.random() * 10000)).padStart(4, "0");
  const choices = new Set([code]);
  while (choices.size < 5) choices.add(String(Math.floor(Math.random() * 10000)).padStart(4, "0"));
  const nonce = Date.now().toString(36);
  // Each button carries a keyed tag. Only the right one is HMAC(user:nonce:choice); the others
  // are keyed on something else, so they look just as random and only the server can tell.
  const buttons = [];
  for (const c of [...choices].sort(() => Math.random() - 0.5)) {
    const tag = await hmac(env, c === code ? `${uid}:${nonce}:${c}` : `${uid}:${nonce}:${c}:decoy`);
    buttons.push({ type: 2, style: 2, label: c, custom_id: `cap:${nonce}:${c}:${tag}` });
  }
  return reply("", {
    embeds: [{ title: "Quick check", color: COLOR, description: "Press the button that shows this code:\n\n" + [...code].map((d) => `\`${d}\``).join(" ") }],
    components: [{ type: 1, components: buttons }],
  });
}

async function answerCaptcha(env, it, ctx) {
  const [, nonce, choice, tag] = it.data.custom_id.split(":");
  const uid = it.member.user.id;
  if (Date.now() - parseInt(nonce, 36) > 120000)
    return update({ content: "That check expired. Press Verify again.", embeds: [], components: [] });
  const ok = tag === (await hmac(env, `${uid}:${nonce}:${choice}`));
  if (!ok) {
    const wait = CONFIG.security.verify_fail_cooldown * 1000;
    await kvPut(env, `vfail:${uid}`, Date.now() + wait, CONFIG.security.verify_fail_cooldown);
    return update({ content: `That wasn't it. Try again in ${CONFIG.security.verify_fail_cooldown}s.`, embeds: [], components: [] });
  }
  try {
    await discord(env, "PUT", `/guilds/${CONFIG.guild_id}/members/${uid}/roles/${CONFIG.roles.member}`, undefined, { reason: "Passed verification" });
  } catch (e) {
    console.log(e.message);
    return update({ content: "I couldn't give you the Member role. Please tell staff.", embeds: [], components: [] });
  }
  ctx.waitUntil(Promise.all([
    log(env, "member-log", { title: "Verified", color: GREEN, description: `<@${uid}>` }),
    CONFIG.channels.general && discord(env, "POST", `/channels/${CONFIG.channels.general}/messages`, {
      content: `👋 Welcome <@${uid}> to **${CONFIG.name}**! Grab the client in <#${CONFIG.channels.download}> and say hi.`,
      allowed_mentions: { users: [uid] } }).catch(() => {}),
  ]));
  return update({ content: "✅ You're verified. Welcome!", embeds: [], components: [] });
}

// ── Tickets ───────────────────────────────────────────────────────────────────

const ticketType = (k) => CONFIG.tickets.find((t) => t.key === k);
const TOPIC = /^ticket:(\d+):(\w+):(\d+)/;

async function openTicketMenu(env, it) {
  const kind = it.data.values[0], uid = it.member.user.id;
  const until = Number(await kvGet(env, `tcool:${uid}`)) || 0;
  if (until > Date.now()) return reply(`You can open another ticket ${relTime(until)}.`);
  const t = ticketType(kind);
  return json({ type: 9, data: { custom_id: `tmodal:${kind}`, title: t.label.slice(0, 45), components: [
    { type: 1, components: [{ type: 4, custom_id: "subject", label: "Subject", style: 1, max_length: 100, required: true }] },
    { type: 1, components: [{ type: 4, custom_id: "details", label: "Details", style: 2, max_length: 1500, required: true,
      placeholder: "What happened? You can add logs or screenshots in the ticket." }] },
  ] } });
}

function ticketFromModal(env, it) {
  const field = (id) => it.data.components.flatMap((r) => r.components).find((c) => c.custom_id === id)?.value || "";
  return createTicket(env, it, it.data.custom_id.split(":")[1], field("subject"), field("details"));
}

async function createTicket(env, it, kind, subject, details) {
  const t = ticketType(kind), user = it.member.user;
  try {
    const channels = await discord(env, "GET", `/guilds/${CONFIG.guild_id}/channels`);
    const open = channels.filter((c) => c.parent_id === CONFIG.categories.tickets && TOPIC.exec(c.topic || "")?.[1] === user.id);
    if (open.length >= CONFIG.security.max_open_tickets)
      return followup(env, it, { content: `You already have an open ticket: <#${open[0].id}>` });

    const num = (Number(await kvGet(env, "ticket_counter")) || channels.filter((c) => c.parent_id === CONFIG.categories.tickets).length) + 1;
    await kvPut(env, "ticket_counter", num);
    await kvPut(env, `tcool:${user.id}`, Date.now() + CONFIG.security.ticket_cooldown * 1000, CONFIG.security.ticket_cooldown);

    const ow = [
      { id: CONFIG.guild_id, type: 0, allow: "0", deny: String(1n << 10n) },
      { id: CONFIG.app_id, type: 1, allow: String(TALK | (1n << 13n) | (1n << 4n)), deny: "0" },
      { id: user.id, type: 1, allow: String(TALK), deny: "0" },
    ];
    if (CONFIG.roles.member) ow.push({ id: CONFIG.roles.member, type: 0, allow: "0", deny: String(1n << 10n) });
    for (const k of t.staff) if (CONFIG.roles[k]) ow.push({ id: CONFIG.roles[k], type: 0, allow: String(TALK | (1n << 13n)), deny: "0" });
    const safe = (user.username || "user").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 20) || "user";
    const ch = await discord(env, "POST", `/guilds/${CONFIG.guild_id}/channels`, {
      name: `${t.emoji}︱${String(num).padStart(4, "0")}-${safe}`, type: 0, parent_id: CONFIG.categories.tickets,
      topic: `ticket:${user.id}:${kind}:${num}`, permission_overwrites: ow,
    }, { reason: `Ticket #${num} for ${user.username}` });

    await discord(env, "POST", `/channels/${ch.id}/messages`, {
      content: `<@${user.id}> the team will be with you soon.`,
      allowed_mentions: { users: [user.id] },
      embeds: [{ title: `${t.emoji} Ticket #${String(num).padStart(4, "0")}: ${clip(subject, 200)}`, color: COLOR,
        description: clip(details, 3500),
        fields: [{ name: "Opened by", value: `<@${user.id}>`, inline: true }, { name: "Type", value: t.label, inline: true },
                 { name: "Status", value: "Waiting for staff", inline: false }],
        footer: { text: "Staff never ask for passwords or send files to run." } }],
      components: [{ type: 1, components: [
        { type: 2, style: 1, label: "Claim", emoji: { name: "🙋" }, custom_id: "ticket:claim" },
        { type: 2, style: 4, label: "Close", emoji: { name: "🔒" }, custom_id: "ticket:close" },
      ] }],
    });
    await log(env, "ticket-transcripts", { title: `Ticket #${String(num).padStart(4, "0")} opened`, color: GREEN,
      description: `<@${user.id}> · ${t.label} · <#${ch.id}>` });
    return followup(env, it, { content: `Your ticket is open: <#${ch.id}>` });
  } catch (e) {
    console.log("ticket failed", e.message);
    return followup(env, it, { content: "Sorry, I couldn't open a ticket. Please tell staff." });
  }
}

function ticketInfo(it) {
  const m = TOPIC.exec(it.channel?.topic || "");
  return m ? { owner: m[1], kind: m[2], num: Number(m[3]) } : null;
}
const canManage = (member, kind) => hasRole(member, ticketType(kind)?.staff || CONFIG.ticket_staff);

function claimTicket(it) {
  const info = ticketInfo(it);
  if (!info || !canManage(it.member, info.kind)) return reply("Only staff can claim tickets.");
  const embed = it.message.embeds[0];
  const status = embed.fields.find((f) => f.name === "Status");
  if (status.value.startsWith("Claimed")) return reply(`Already ${status.value.toLowerCase()}.`);
  status.value = `Claimed by <@${it.member.user.id}>`;
  return update({ embeds: [embed] });
}

function closeTicket(it) {
  const info = ticketInfo(it);
  if (!info) return reply("This isn't a ticket.");
  if (it.member.user.id !== info.owner && !canManage(it.member, info.kind)) return reply("You can't close this ticket.");
  return reply("Close this ticket? A transcript will be saved.", { components: [{ type: 1, components: [
    { type: 2, style: 4, label: "Close ticket", custom_id: "ticket:confirm" }] }] });
}

async function finishClose(env, it) {
  const info = ticketInfo(it), chId = it.channel_id, closer = it.member.user;
  try {
    let before, all = [];
    for (;;) {
      const page = await discord(env, "GET", `/channels/${chId}/messages?limit=100${before ? `&before=${before}` : ""}`);
      all = all.concat(page);
      if (page.length < 100) break;
      before = page[page.length - 1].id;
    }
    all.reverse();
    let claimed = "Never claimed";
    const lines = all.map((m) => {
      let body = m.content || "";
      for (const e of m.embeds || []) {
        body += ` [embed: ${e.title || ""} ${e.description || ""}]`;
        const s = (e.fields || []).find((f) => f.name === "Status" && f.value.startsWith("Claimed"));
        if (s) claimed = s.value;
      }
      for (const a of m.attachments || []) body += ` [file: ${a.url}]`;
      return `[${m.timestamp.slice(0, 19).replace("T", " ")}] ${m.author.username} (${m.author.id}): ${body}`;
    });
    const num = String(info.num).padStart(4, "0");
    const label = ticketType(info.kind)?.label || info.kind;
    const text = `Ticket #${num} · ${label}\nOpened by ${info.owner} · Closed by ${closer.username} (${closer.id}) at ${new Date().toISOString()}\n\n${lines.join("\n")}`;
    const send = async (channelId, payload) => {
      const form = new FormData();
      form.append("payload_json", JSON.stringify({ ...payload, allowed_mentions: { parse: [] }, attachments: [{ id: 0, filename: `ticket-${num}.txt` }] }));
      form.append("files[0]", new Blob([text], { type: "text/plain" }), `ticket-${num}.txt`);
      return discord(env, "POST", `/channels/${channelId}/messages`, undefined, { form });
    };
    if (CONFIG.channels["ticket-transcripts"])
      await send(CONFIG.channels["ticket-transcripts"], { embeds: [{ title: `Ticket #${num} closed`, color: GREY, timestamp: new Date().toISOString(),
        description: `Opened by <@${info.owner}> · Closed by <@${closer.id}>\n${claimed} · ${all.length} messages` }] });
    try {
      const dm = await discord(env, "POST", "/users/@me/channels", { recipient_id: info.owner });
      await send(dm.id, { content: `Your ticket #${num} was closed. Here's a copy.` });
    } catch (e) { /* DMs closed */ }
    await new Promise((r) => setTimeout(r, 2000));
    await discord(env, "DELETE", `/channels/${chId}`, undefined, { reason: `Ticket closed by ${closer.username}` });
  } catch (e) {
    console.log("close failed", e.message);
    await followup(env, it, { content: "I couldn't close the ticket. Please tell an Admin." }).catch(() => {});
  }
}

// ── Commands ──────────────────────────────────────────────────────────────────

const opt = (it, name) => it.data.options?.find((o) => o.name === name)?.value;
const MOD = ["mod", ...CONFIG.admins];

async function command(env, it, ctx) {
  const name = it.data.name, m = it.member;
  const deny = () => reply("You don't have permission to use this.");

  if (name === "verify") {
    if (!hasRole(m, MOD)) return deny();
    const target = opt(it, "member");
    await discord(env, "PUT", `/guilds/${CONFIG.guild_id}/members/${target}/roles/${CONFIG.roles.member}`, undefined,
      { reason: `Manually verified by ${m.user.username}` });
    ctx.waitUntil(log(env, "mod-log", { title: "Manually verified", color: GREEN, description: `<@${target}>\nBy <@${m.user.id}>` }));
    return reply(`Verified <@${target}>.`);
  }

  if (name === "raidmode") {
    if (!hasRole(m, MOD)) return deny();
    const on = opt(it, "mode") === "on";
    if (!env.KV) return reply("Raid mode needs the KV storage binding; ask an Admin to add it.");
    await kvPut(env, "raid", on ? "on" : "off");
    ctx.waitUntil(log(env, "security-alerts", { title: `🚨 Raid mode ${on ? "on" : "off"}`, color: on ? RED : GREEN,
      description: `Set by <@${m.user.id}>.${on ? " Verification is paused." : ""}` }));
    return reply(`Raid mode ${on ? "on: verification is paused" : "off"}.`);
  }

  if (name === "lockdown" || name === "unlock") {
    if (!hasRole(m, MOD)) return deny();
    ctx.waitUntil(setLock(env, it, name === "lockdown", opt(it, "channel")));
    return deferred();
  }

  if (name === "purge") {
    if (!hasRole(m, MOD)) return deny();
    ctx.waitUntil(purge(env, it, opt(it, "count"), opt(it, "user")));
    return deferred();
  }

  if (name === "ticket-add" || name === "ticket-remove") {
    const info = ticketInfo(it);
    if (!info) return reply("Use this inside a ticket.");
    if (!canManage(m, info.kind)) return reply("Only staff on this ticket can do that.");
    const target = opt(it, "member");
    if (name === "ticket-add")
      await discord(env, "PUT", `/channels/${it.channel_id}/permissions/${target}`, { type: 1, allow: String(TALK), deny: "0" });
    else await discord(env, "DELETE", `/channels/${it.channel_id}/permissions/${target}`);
    return json({ type: 4, data: { content: `${name === "ticket-add" ? "Added" : "Removed"} <@${target}>.`, allowed_mentions: { parse: [] } } });
  }

  if (name === "panels") {
    if (!hasRole(m, CONFIG.admins)) return deny();
    ctx.waitUntil(postPanels(env).then(() => followup(env, it, { content: "Panels posted." })));
    return deferred();
  }
  return moreCommands(env, it, ctx);
}

async function setLock(env, it, locked, channelId) {
  try {
    const all = await discord(env, "GET", `/guilds/${CONFIG.guild_id}/channels`);
    const cats = CONFIG.lockdown_categories.map((k) => CONFIG.categories[k]);
    const targets = channelId ? all.filter((c) => c.id === channelId) : all.filter((c) => cats.includes(c.parent_id));
    const roleId = CONFIG.roles.member;
    let done = 0;
    for (const ch of targets) {
      const ow = (ch.permission_overwrites || []).find((o) => o.id === roleId) || { allow: "0", deny: "0" };
      let allow = BigInt(ow.allow), deny = BigInt(ow.deny);
      const key = `lock:${ch.id}`;
      if (locked) {
        if (await kvGet(env, key)) continue;
        await kvPut(env, key, JSON.stringify({ allow: ow.allow, deny: ow.deny }));
        for (const bit of Object.values(LOCK_BITS)) { allow &= ~bit; deny |= bit; }
      } else {
        const prev = await kvGet(env, key);
        if (!prev && env.KV) continue;
        if (prev) { const p = JSON.parse(prev); allow = BigInt(p.allow); deny = BigInt(p.deny); }
        else for (const bit of Object.values(LOCK_BITS)) deny &= ~bit; // no memory: just lift the lock
        await kvDel(env, key);
      }
      await discord(env, "PUT", `/channels/${ch.id}/permissions/${roleId}`, { type: 0, allow: String(allow), deny: String(deny) },
        { reason: `${locked ? "Lockdown" : "Unlock"} by ${it.member.user.username}` });
      done++;
    }
    const word = locked ? "Locked" : "Unlocked";
    await followup(env, it, { content: `${word} ${done} channel(s).` });
    await log(env, "mod-log", { title: word, color: locked ? RED : GREEN,
      description: `${done} channel(s)${channelId ? `: <#${channelId}>` : " (server-wide)"}\nBy <@${it.member.user.id}>` });
    if (locked && !channelId)
      await log(env, "security-alerts", { title: "🚨 Server lockdown", color: ORANGE,
        description: `<@${it.member.user.id}> locked the member channels. Run \`/unlock\` to undo.` });
  } catch (e) {
    console.log("lock failed", e.message);
    await followup(env, it, { content: "Lockdown failed partway. Check the channel permissions." }).catch(() => {});
  }
}

async function purge(env, it, count, userId) {
  try {
    const msgs = await discord(env, "GET", `/channels/${it.channel_id}/messages?limit=100`);
    const cutoff = Date.now() - 13.9 * 86400000;
    const ids = msgs.filter((x) => (!userId || x.author.id === userId) && snowflakeTime(x.id) > cutoff).slice(0, count).map((x) => x.id);
    if (ids.length === 1) await discord(env, "DELETE", `/channels/${it.channel_id}/messages/${ids[0]}`);
    else if (ids.length > 1) await discord(env, "POST", `/channels/${it.channel_id}/messages/bulk-delete`, { messages: ids },
      { reason: `/purge by ${it.member.user.username}` });
    await followup(env, it, { content: `Deleted ${ids.length} message(s).` });
    await log(env, "mod-log", { title: "Purge", color: ORANGE,
      description: `${ids.length} message(s) in <#${it.channel_id}>${userId ? ` from <@${userId}>` : ""}\nBy <@${it.member.user.id}>` });
  } catch (e) {
    console.log("purge failed", e.message);
    await followup(env, it, { content: "Purge failed." }).catch(() => {});
  }
}

// ── Moderation, member tools and reports ─────────────────────────────────────

const STAFF_KEYS = ["mod", "developer", ...CONFIG.admins];
const isAdmin = (m) => hasRole(m, CONFIG.admins);
const fmtDur = (min) => min >= 1440 ? `${min / 1440} day(s)` : min >= 60 ? `${min / 60} hour(s)` : `${min} minute(s)`;

function target(it, name = "member") {
  const id = opt(it, name);
  return { id, user: it.data.resolved?.users?.[id], member: it.data.resolved?.members?.[id] };
}

// Can `actor` moderate `t`? Never yourself, the bot, or staff unless you're an Admin.
function guard(it, t) {
  if (!t.id) return "Pick someone.";
  if (t.id === it.member.user.id) return "You can't do that to yourself.";
  if (t.id === CONFIG.app_id || t.user?.bot) return "You can't do that to a bot.";
  if (t.member && hasRole({ roles: t.member.roles, permissions: t.member.permissions || "0" }, STAFF_KEYS) && !isAdmin(it.member))
    return "Only Admins can take action against staff.";
  return null;
}

async function dm(env, userId, embed) {
  try {
    const ch = await discord(env, "POST", "/users/@me/channels", { recipient_id: userId });
    await discord(env, "POST", `/channels/${ch.id}/messages`, { embeds: [{ color: ORANGE, ...embed, footer: { text: CONFIG.name } }] });
    return true;
  } catch (e) { return false; }
}

async function getWarnings(env, uid) {
  try { return JSON.parse((await kvGet(env, `warns:${uid}`)) || "[]"); } catch (e) { return []; }
}

async function modAction(env, it, kind, t, reason, extra = {}) {
  const by = it.member.user.id;
  const color = { Warned: ORANGE, "Timed out": ORANGE, Kicked: RED, Banned: RED, Unbanned: GREEN, "Timeout removed": GREEN }[kind] ?? ORANGE;
  await log(env, "mod-log", { title: kind, color,
    description: `<@${t.id}> (\`${t.id}\`)\nBy <@${by}>\nReason: ${clip(reason || "none", 500)}${extra.detail ? `\n${extra.detail}` : ""}` });
}

async function moreCommands(env, it, ctx) {
  const name = it.data.name, m = it.member;
  const deny = () => reply("You don't have permission to use this.");
  const reason = opt(it, "reason") || "";

  // Everyone
  if (name === "help") {
    const staff = hasRole(m, STAFF_KEYS);
    const lines = [
      "**For everyone**",
      `\`/ticket\` open a private ticket with staff (or use <#${CONFIG.channels["create-ticket"]}>)`,
      "**Report message / Report user**: long-press (or right-click) a message or person → Apps",
      `Download: <#${CONFIG.channels.download}> · Install help: <#${CONFIG.channels["install-guide"]}> · Rules: <#${CONFIG.channels.rules}>`,
    ];
    if (staff) lines.push("", "**Staff**",
      "`/warn` `/warnings` `/timeout` `/kick` `/userinfo` `/slowmode` `/purge` `/lockdown` `/unlock` `/raidmode` `/verify`",
      "`/ticket-add` `/ticket-remove` in tickets · Admins also: `/ban` `/unban` `/announce` `/panels`",
      "Every action is logged in mod-log and the member gets a DM with your reason.");
    return reply("", { embeds: [{ title: `${CONFIG.name} bot`, color: COLOR, description: lines.join("\n"),
      footer: { text: "Terms & privacy: fish-claude-bot.pages.dev/terms" } }] });
  }

  if (name === "ticket") {
    const until = Number(await kvGet(env, `tcool:${m.user.id}`)) || 0;
    if (until > Date.now()) return reply(`You can open another ticket ${relTime(until)}.`);
    return reply("What do you need help with?", { components: panels().ticket.components });
  }

  // Context menus: Report message / Report user
  if (name === "Report message" || name === "Report user") {
    const tid = it.data.target_id;
    let subject, details;
    if (name === "Report message") {
      const msg = it.data.resolved.messages[tid];
      subject = `Report: message by ${msg.author.username}`;
      details = `Reported message by <@${msg.author.id}> (\`${msg.author.id}\`) in <#${it.channel_id}>:\n` +
        `https://discord.com/channels/${CONFIG.guild_id}/${it.channel_id}/${tid}\n\n> ${clip(msg.content || "(no text)", 1500).replace(/\n/g, "\n> ")}` +
        ((msg.attachments || []).length ? `\n\nAttachments: ${msg.attachments.map((a) => a.url).join(" ")}` : "");
    } else {
      const u = it.data.resolved.users[tid];
      subject = `Report: ${u.username}`;
      details = `Reported user: <@${u.id}> (\`${u.id}\`), account created ${relTime(snowflakeTime(u.id))}.`;
    }
    if (tid === m.user.id || it.data.resolved?.users?.[tid]?.id === m.user.id) return reply("You can't report yourself.");
    ctx.waitUntil(createTicket(env, it, "report", subject, details + "\n\nPlease add any extra context below."));
    return deferred();
  }

  // Staff (Mod+)
  const MODS = ["mod", ...CONFIG.admins];
  if (name === "warn") {
    if (!hasRole(m, MODS)) return deny();
    const t = target(it), err = guard(it, t);
    if (err) return reply(err);
    const list = await getWarnings(env, t.id);
    list.push({ reason, by: m.user.id, at: Date.now() });
    await kvPut(env, `warns:${t.id}`, JSON.stringify(list.slice(-50)));
    const sent = await dm(env, t.id, { title: `You were warned in ${CONFIG.name}`, description: `Reason: ${reason}\n\nPlease read the rules. Repeated warnings lead to timeouts or bans.` });
    ctx.waitUntil(modAction(env, it, "Warned", t, reason, { detail: `Warning #${list.length}${sent ? "" : " · DMs closed"}` }));
    return reply(`Warned <@${t.id}> (warning #${list.length})${sent ? "" : ". Their DMs are closed, so they weren't notified"}.`);
  }

  if (name === "warnings") {
    if (!hasRole(m, MODS)) return deny();
    const t = target(it), list = await getWarnings(env, t.id);
    if (opt(it, "clear")) {
      if (!isAdmin(m)) return reply("Only Admins can clear warnings.");
      await kvDel(env, `warns:${t.id}`);
      ctx.waitUntil(modAction(env, it, "Warnings cleared", t, `${list.length} removed`));
      return reply(`Cleared ${list.length} warning(s) for <@${t.id}>.`);
    }
    if (!list.length) return reply(`<@${t.id}> has no warnings.`);
    return reply("", { embeds: [{ title: `Warnings: ${t.user?.username || t.id}`, color: ORANGE,
      description: list.slice(-15).map((w, i) => `**${list.length - Math.min(15, list.length) + i + 1}.** ${clip(w.reason, 200)} · by <@${w.by}> ${relTime(w.at)}`).join("\n") }] });
  }

  if (name === "timeout") {
    if (!hasRole(m, MODS)) return deny();
    const t = target(it), err = guard(it, t);
    if (err) return reply(err);
    const minutes = opt(it, "duration");
    const until = minutes ? new Date(Date.now() + minutes * 60000).toISOString() : null;
    await discord(env, "PATCH", `/guilds/${CONFIG.guild_id}/members/${t.id}`, { communication_disabled_until: until },
      { reason: `${m.user.username}: ${reason || "no reason"}` });
    if (minutes) await dm(env, t.id, { title: `You were timed out in ${CONFIG.name}`, description: `For ${fmtDur(minutes)}.\nReason: ${reason || "none given"}` });
    ctx.waitUntil(modAction(env, it, minutes ? "Timed out" : "Timeout removed", t, reason, { detail: minutes ? `For ${fmtDur(minutes)}` : "" }));
    return reply(minutes ? `Timed out <@${t.id}> for ${fmtDur(minutes)}.` : `Removed <@${t.id}>'s timeout.`);
  }

  if (name === "kick") {
    if (!hasRole(m, MODS)) return deny();
    const t = target(it), err = guard(it, t);
    if (err) return reply(err);
    await dm(env, t.id, { title: `You were kicked from ${CONFIG.name}`, color: RED, description: `Reason: ${reason}\n\nYou can rejoin with an invite, but please read the rules first.` });
    await discord(env, "DELETE", `/guilds/${CONFIG.guild_id}/members/${t.id}`, undefined, { reason: `${m.user.username}: ${reason}` });
    ctx.waitUntil(modAction(env, it, "Kicked", t, reason));
    return reply(`Kicked <@${t.id}>.`);
  }

  if (name === "userinfo") {
    if (!hasRole(m, STAFF_KEYS)) return deny();
    const t = target(it), u = t.user || {}, mem = t.member;
    const warns = await getWarnings(env, t.id);
    const fields = [
      { name: "Account created", value: relTime(snowflakeTime(t.id)), inline: true },
      { name: "Joined", value: mem?.joined_at ? relTime(Date.parse(mem.joined_at)) : "not in server", inline: true },
      { name: "Warnings", value: String(warns.length), inline: true },
      { name: "Roles", value: mem?.roles?.length ? mem.roles.map((r) => `<@&${r}>`).join(" ") : "none", inline: false },
    ];
    if (mem?.communication_disabled_until && Date.parse(mem.communication_disabled_until) > Date.now())
      fields.push({ name: "Timed out until", value: `<t:${Math.floor(Date.parse(mem.communication_disabled_until) / 1000)}:f>`, inline: false });
    const avatar = u.avatar ? `https://cdn.discordapp.com/avatars/${t.id}/${u.avatar}.png?size=128` : undefined;
    return reply("", { embeds: [{ title: u.global_name || u.username || t.id, color: COLOR, description: `<@${t.id}> · \`${t.id}\``,
      thumbnail: avatar ? { url: avatar } : undefined, fields }] });
  }

  if (name === "slowmode") {
    if (!hasRole(m, MODS)) return deny();
    const secs = opt(it, "seconds");
    await discord(env, "PATCH", `/channels/${it.channel_id}`, { rate_limit_per_user: secs }, { reason: `/slowmode by ${m.user.username}` });
    ctx.waitUntil(log(env, "mod-log", { title: "Slowmode", color: GREY, description: `<#${it.channel_id}>: ${secs ? `${secs}s` : "off"}\nBy <@${m.user.id}>` }));
    return reply(secs ? `Slowmode set to ${secs}s.` : "Slowmode off.");
  }

  // Admin+
  if (name === "ban") {
    if (!isAdmin(m)) return reply("Only Admins can ban. Ask in staff chat with evidence.");
    const t = target(it), err = guard(it, t);
    if (err) return reply(err);
    const days = opt(it, "delete_days") ?? 0;
    await dm(env, t.id, { title: `You were banned from ${CONFIG.name}`, color: RED,
      description: `Reason: ${reason}\n\nIf you think this was a mistake, you can appeal by messaging a staff member you trust or rejoining after the ban is lifted.` });
    await discord(env, "PUT", `/guilds/${CONFIG.guild_id}/bans/${t.id}`, { delete_message_seconds: days * 86400 }, { reason: `${m.user.username}: ${reason}` });
    ctx.waitUntil(modAction(env, it, "Banned", t, reason, { detail: days ? `Deleted ${days} day(s) of messages` : "" }));
    return reply(`Banned <@${t.id}>.`);
  }

  if (name === "unban") {
    if (!isAdmin(m)) return deny();
    const id = String(opt(it, "user_id") || "").replace(/\D/g, "");
    if (!id) return reply("Give a user ID.");
    try {
      await discord(env, "DELETE", `/guilds/${CONFIG.guild_id}/bans/${id}`, undefined, { reason: `${m.user.username}: ${reason || "no reason"}` });
    } catch (e) { return reply("That user isn't banned (or the ID is wrong)."); }
    ctx.waitUntil(modAction(env, it, "Unbanned", { id }, reason));
    return reply(`Unbanned <@${id}>.`);
  }

  if (name === "announce") {
    if (!hasRole(m, ["developer", ...CONFIG.admins])) return deny();
    const ch = opt(it, "channel") || CONFIG.channels.announcements;
    return json({ type: 9, data: { custom_id: `announce:${ch}:${opt(it, "ping") || "none"}`, title: "New announcement", components: [
      { type: 1, components: [{ type: 4, custom_id: "title", label: "Title", style: 1, max_length: 200, required: true }] },
      { type: 1, components: [{ type: 4, custom_id: "body", label: "Message", style: 2, max_length: 3800, required: true }] },
      { type: 1, components: [{ type: 4, custom_id: "image", label: "Image URL (optional)", style: 1, required: false, max_length: 500 }] },
    ] } });
  }

  return reply("Unknown command.");
}

async function announceSubmit(env, it, ctx) {
  if (!hasRole(it.member, ["developer", ...CONFIG.admins])) return reply("You don't have permission to use this.");
  const [, ch, ping] = it.data.custom_id.split(":");
  const field = (id) => it.data.components.flatMap((r) => r.components).find((c) => c.custom_id === id)?.value || "";
  const image = field("image").trim();
  const embed = { title: field("title"), description: field("body"), color: COLOR, timestamp: new Date().toISOString(),
    footer: { text: `${CONFIG.name} · posted by ${it.member.user.username}` } };
  if (/^https:\/\/\S+$/.test(image)) embed.image = { url: image };
  const content = ping === "everyone" ? "@everyone" : ping === "here" ? "@here" : undefined;
  try {
    const msg = await discord(env, "POST", `/channels/${ch}/messages`, { content, embeds: [embed],
      allowed_mentions: { parse: content ? ["everyone"] : [] } });
    ctx.waitUntil(discord(env, "POST", `/channels/${ch}/messages/${msg.id}/crosspost`).catch(() => {}));
    ctx.waitUntil(log(env, "mod-log", { title: "Announcement posted", color: GREY, description: `In <#${ch}> by <@${it.member.user.id}>` }));
    return reply(`Posted in <#${ch}>.`);
  } catch (e) {
    console.log(e.message);
    return reply("I couldn't post there. Check I can see and talk in that channel.");
  }
}

// ── Panels ────────────────────────────────────────────────────────────────────

export function panels() {
  const s = CONFIG.security;
  return {
    verify: {
      embeds: [{ title: `Welcome to ${CONFIG.name}`, color: COLOR, description:
        "Read the rules, then press **Verify** to unlock the server.\n\nYou'll be asked to pick a code to prove you're human. " +
        `Accounts younger than ${s.min_account_age_days} days can't verify automatically. If that's you, wait a little or ask staff.` }],
      components: [{ type: 1, components: [{ type: 2, style: 3, label: "Verify", emoji: { name: "✅" }, custom_id: "verify:start" }] }],
    },
    ticket: {
      embeds: [{ title: "Open a Ticket", color: COLOR, description:
        "Need private help from the team? Pick a category below and a private channel will open that only you and staff can see.\n\n" +
        CONFIG.tickets.map((t) => `${t.emoji} **${t.label}**`).join("\n") +
        "\n\nStaff will **never** ask for your password or send you files to run." }],
      components: [{ type: 1, components: [{ type: 3, custom_id: "ticket:open", placeholder: "Choose a ticket type…",
        options: CONFIG.tickets.map((t) => ({ label: t.label, value: t.key, emoji: { name: t.emoji } })) }] }],
    },
  };
}

async function postPanels(env) {
  const p = panels();
  await discord(env, "POST", `/channels/${CONFIG.channels.verify}/messages`, p.verify);
  await discord(env, "POST", `/channels/${CONFIG.channels["create-ticket"]}/messages`, p.ticket);
}

// ── Entry ─────────────────────────────────────────────────────────────────────

async function handle(env, it, ctx) {
  if (it.type === 1) return json({ type: 1 });
  if (!it.member || it.guild_id !== CONFIG.guild_id) return reply("This bot only works in its home server.");
  if (!env.DISCORD_TOKEN) return reply("The bot isn't fully set up yet (missing DISCORD_TOKEN). Tell an Admin.");

  if (it.type === 2) return command(env, it, ctx);
  if (it.type === 3) {
    const id = it.data.custom_id;
    if (id === "verify:start") return startVerify(env, it);
    if (id.startsWith("cap:")) return answerCaptcha(env, it, ctx);
    if (id === "ticket:open") return openTicketMenu(env, it);
    if (id === "ticket:claim") return claimTicket(it);
    if (id === "ticket:close") return closeTicket(it);
    if (id === "ticket:confirm") {
      ctx.waitUntil(finishClose(env, it));
      return json({ type: 4, data: { content: "🔒 Closing: saving the transcript…" } });
    }
  }
  if (it.type === 5 && it.data.custom_id.startsWith("announce:")) return announceSubmit(env, it, ctx);
  if (it.type === 5 && it.data.custom_id.startsWith("tmodal:")) {
    ctx.waitUntil(ticketFromModal(env, it));
    return deferred();
  }
  return reply("I don't know how to handle that.");
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (request.method === "GET" && PAGES[url.pathname])
      return new Response(PAGES[url.pathname], { headers: { "content-type": "text/html; charset=utf-8",
        "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'; img-src https:", "x-content-type-options": "nosniff" } });
    if (request.method === "GET")
      return new Response(`${CONFIG.name} bot is running.\n\nTerms of Service: /terms\nPrivacy Policy: /privacy`, { status: 200 });
    if (request.method !== "POST" || url.pathname !== "/interactions") return new Response("Not found", { status: 404 });
    const body = await request.text();
    if (!(await verifySignature(request, body))) return new Response("Bad signature", { status: 401 });
    try {
      return await handle(env, JSON.parse(body), ctx);
    } catch (e) {
      console.log("interaction failed", e.stack || e.message);
      return reply("Something went wrong. Please try again or tell staff.");
    }
  },
};
